--
-- Table structure for table `inventory_logs`
--

DROP TABLE IF EXISTS `inventory_logs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_logs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `part_id` int DEFAULT NULL,
  `change_type` varchar(20) NOT NULL COMMENT 'in, out, check',
  `change_qty` int NOT NULL,
  `operator_id` int DEFAULT NULL,
  `remark` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `before_stock` int NOT NULL COMMENT '变动前库存',
  `after_stock` int NOT NULL COMMENT '变动后库存',
  PRIMARY KEY (`id`),
  KEY `operator_id` (`operator_id`),
  KEY `ix_inventory_logs_part_created_at` (`part_id`,`created_at`),
  KEY `ix_inventory_logs_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=16209 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

